import numpy as np, itertools
def readxyz(p):
    lines = open(p).read().split('\n')
    n = int(lines[0]); syms=[]; pos=[]
    for l in lines[2:2+n]:
        q=l.split(); syms.append(q[0]); pos.append([float(x) for x in q[1:4]])
    return syms, np.array(pos)
syms, pos = readxyz('opt1.xyz')
cov = {'H':0.31,'C':0.76,'Si':1.11,'P':1.07,'Cl':1.02,'Zr':1.60}
bonds = {}
for i,j in itertools.combinations(range(len(syms)),2):
    d = np.linalg.norm(pos[i]-pos[j])
    if d < cov[syms[i]]+cov[syms[j]]+0.45:
        bonds.setdefault(i,[]).append(j); bonds.setdefault(j,[]).append(i)
for i in range(len(syms)):
    nb = bonds.get(i,[])
    if syms[i] in ('Zr','P','Si','Cl'):
        print(syms[i], i, '->', [(syms[j], j, round(np.linalg.norm(pos[i]-pos[j]),2)) for j in nb])
# check H count per C
for i in range(len(syms)):
    if syms[i]=='C':
        hs = [j for j in bonds.get(i,[]) if syms[j]=='H']
        cs = [j for j in bonds.get(i,[]) if syms[j]=='C']
        si = [j for j in bonds.get(i,[]) if syms[j]=='Si']
        p = [j for j in bonds.get(i,[]) if syms[j]=='P']
        zr = [j for j in bonds.get(i,[]) if syms[j]=='Zr']
        tot = len(hs)+len(cs)+len(si)+len(p)+len(zr)
        if not (2 <= tot <= 4):
            print("ODD C", i, len(hs), len(cs), len(si), len(p), len(zr))
print("total atoms", len(syms))
